  "lib/global/colors.dart": "import 'package:flutter/material.dart';\n\nconst Color kTerminalGreen = Colors.white;\nconst Color kTerminalDark = Color(0xFF0A1A0A);\nconst Color kBackgroundColor = Colors.black;\nconst Color kTextColor = Colors.white;\nconst Color kAccentColor = Color(0xFFB072FF);\n",
  "lib/widgets/selectable_highlight_view.dart": "import 'package:flutter/material.dart';\nimport 'package:highlight/highlight.dart' show highlight, Node;\n\nclass SelectableHighlightView extends StatelessWidget {\n  final String source;\n  final String? language;\n  final Map<String, TextStyle> theme;\n  final EdgeInsetsGeometry? padding;\n  final TextStyle? textStyle;\n\n  SelectableHighlightView(\n    String input, {\n    super.key,\n    this.language,\n    this.theme = const {},\n    this.padding,\n    this.textStyle,\n    int tabSize = 8,\n  }) : source = input.replaceAll('\\t', ' ' * tabSize);\n\n  List<TextSpan> _convert(List<Node> nodes) {\n    List<TextSpan> spans = [];\n    var currentSpans = spans;\n    List<List<TextSpan>> stack = [];\n\n    void _traverse(Node node) {\n      if (node.value != null) {\n        currentSpans.add(\n          node.className == null\n              ? TextSpan(text: node.value)\n              : TextSpan(text: node.value, style: theme[node.className!]),\n        );\n      } else if (node.children != null) {\n        List<TextSpan> tmp = [];\n        currentSpans.add(\n          TextSpan(children: tmp, style: theme[node.className!]),\n        );\n        stack.add(currentSpans);\n        currentSpans = tmp;\n\n        for (var n in node.children!) {\n          _traverse(n);\n          if (n == node.children!.last) {\n            currentSpans = stack.isEmpty ? spans : stack.removeLast();\n          }\n        }\n      }\n    }\n\n    for (var node in nodes) {\n      _traverse(node);\n    }\n\n    return spans;\n  }\n\n  static const _rootKey = 'root';\n  static const _defaultFontColor = Color(0xff000000);\n  static const _defaultBackgroundColor = Color(0xffffffff);\n  static const _defaultFontFamily = 'monospace';\n\n  @override\n  Widget build(BuildContext context) {\n    var style = TextStyle(\n      fontFamily: _defaultFontFamily,\n      color: theme[_rootKey]?.color ?? _defaultFontColor,\n    );\n    if (textStyle != null) {\n      style = style.merge(textStyle);\n    }\n\n    return Container(\n      color: theme[_rootKey]?.backgroundColor ?? _defaultBackgroundColor,\n      padding: padding,\n      child: Text.rich(\n        TextSpan(\n          style: style,\n          children: _convert(\n            highlight.parse(source, language: language).nodes!,\n          ),\n        ),\n        softWrap: false,\n      ),\n    );\n  }\n}\n",
  "lib/widgets/loading_waveform.dart": "import 'dart:math' as math;\nimport 'package:archbtw_sh/global/colors.dart';\nimport 'package:flutter/material.dart';\n\nclass WaveformLoader extends StatefulWidget {\n  final double height;\n  final double barWidth;\n  final Color? color;\n\n  const WaveformLoader({\n    super.key,\n    this.height = 50.0,\n    this.barWidth = 4.0,\n    this.color,\n  });\n\n  @override\n  State<WaveformLoader> createState() => _WaveformLoaderState();\n}\n\nclass _WaveformLoaderState extends State<WaveformLoader>\n    with SingleTickerProviderStateMixin {\n  late AnimationController _controller;\n\n  @override\n  void initState() {\n    super.initState();\n    _controller = AnimationController(\n      vsync: this,\n      duration: const Duration(milliseconds: 1200),\n    )..repeat();\n  }\n\n  @override\n  void dispose() {\n    _controller.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final color = Colors.white;\n\n    return SizedBox(\n      height: widget.height,\n      child: Row(\n        mainAxisSize: MainAxisSize.min,\n        mainAxisAlignment: MainAxisAlignment.center,\n        crossAxisAlignment: CrossAxisAlignment.center,\n        children: List.generate(5, (index) {\n          final double delayFactor = index * (1 / 12);\n\n          return AnimatedBuilder(\n            animation: _controller,\n            builder: (context, child) {\n              double t = (_controller.value - delayFactor) % 1.0;\n\n              double sinVal = math.sin(t * 2 * math.pi);\n\n              double normalized = (sinVal + 1) / 2;\n              double scale = 0.1 + (normalized * 0.9);\n\n              return Container(\n                width: widget.barWidth,\n                height: widget.height * scale,\n                margin: const EdgeInsets.symmetric(horizontal: 3.0),\n                decoration: BoxDecoration(\n                  color: color,\n                  borderRadius: BorderRadius.circular(99),\n                ),\n              );\n            },\n          );\n        }),\n      ),\n    );\n  }\n}\n",
  "lib/widgets/social_icons.dart": "import 'package:archbtw_sh/global/colors.dart';\nimport 'package:archbtw_sh/global/helpers.dart';\nimport 'package:flutter/material.dart';\nimport 'package:font_awesome_flutter/font_awesome_flutter.dart';\n\nclass SocialIcon extends StatelessWidget {\n  final dynamic icon;\n  final String? url;\n  final double iconSize;\n  final VoidCallback? onPressed;\n  final String? tooltip;\n  final Color? color;\n  final Color? hoverColor;\n\n  const SocialIcon({\n    super.key,\n    required this.icon,\n    this.url,\n    this.iconSize = 18.0,\n    this.onPressed,\n    this.tooltip,\n    this.color,\n    this.hoverColor,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    final effectiveHover = hoverColor ?? kAccentColor;\n    final Widget iconWidget = icon is FaIconData\n        ? FaIcon(\n            icon as FaIconData,\n            color: color ?? Colors.grey,\n            size: iconSize,\n          )\n        : Icon(\n            icon as IconData,\n            color: color ?? Colors.grey,\n            size: iconSize,\n          );\n\n    return IconButton(\n      tooltip: tooltip,\n      icon: iconWidget,\n      onPressed: onPressed ??\n          () {\n            if (url != null) openUrl(url!);\n          },\n      splashColor: effectiveHover.withValues(alpha: 0.3),\n      hoverColor: effectiveHover.withValues(alpha: 0.1),\n    );\n  }\n}\n",
  "lib/widgets/header.dart": "import 'package:archbtw_sh/global/colors.dart';\nimport 'package:archbtw_sh/widgets/nav_link.dart';\nimport 'package:flutter/material.dart';\n\nclass Header extends StatelessWidget {\n  final int currentIndex;\n  final Function(int) onItemTapped;\n\n  const Header({\n    required this.currentIndex,\n    required this.onItemTapped,\n  });\n\n  static const double kTabletBreakpoint = 768.0;\n\n\n  @override\n  Widget build(BuildContext context) {\n    return LayoutBuilder(\n      builder: (context, constraints) {\n        \n        final bool isDesktop = constraints.maxWidth >= kTabletBreakpoint;\n\n        final double titleFontSize = isDesktop ? 22 : 18;\n        final double navLinkFontSize = isDesktop ? 16 : 14;\n        \n        final EdgeInsets padding = isDesktop\n            ? const EdgeInsets.symmetric(horizontal: 48.0, vertical: 16.0)\n            : const EdgeInsets.symmetric(horizontal: 16.0, vertical: 16.0);\n\n        final headerContent = Row(\n          mainAxisAlignment: MainAxisAlignment.spaceBetween,\n          crossAxisAlignment: CrossAxisAlignment.center,\n          children: [\n            TextButton(\n              onPressed: () => onItemTapped(0),\n              style: TextButton.styleFrom(\n                splashFactory: NoSplash.splashFactory,\n                overlayColor: Colors.transparent,\n                padding: EdgeInsets.zero,\n                alignment: Alignment.centerLeft,\n              ),\n              child: Text(\n                '// archBTW.',\n                style: TextStyle(\n                  color: kTextColor,\n                  fontSize: titleFontSize,\n                  fontWeight: FontWeight.bold,\n                  letterSpacing: 1.5,\n                  fontFamily: 'JetBrainsMono',\n                ),\n              ),\n            ),\n            Row(\n              mainAxisAlignment: MainAxisAlignment.start,\n              children: [\n                NavLink(\n                  title: 'about',\n                  index: 1,\n                  currentIndex: currentIndex,\n                  onTap: () => onItemTapped(1),\n                  fontSize: navLinkFontSize,\n                ),\n                NavLink(\n                  title: 'music',\n                  index: 2,\n                  currentIndex: currentIndex,\n                  onTap: () => onItemTapped(2),\n                  fontSize: navLinkFontSize,\n                ),\n                NavLink(\n                  title: 'merch',\n                  index: 3,\n                  currentIndex: currentIndex,\n                  onTap: () => onItemTapped(3),\n                  fontSize: navLinkFontSize,\n                ),\n              ],\n            ),\n          ],\n        );\n        return Container(\n          color: kBackgroundColor,\n          child: Padding(\n            padding: padding,\n            child: headerContent,\n          ),\n        );\n      },\n    );\n  }\n}",
  "lib/widgets/nav_link.dart": "import 'package:archbtw_sh/global/colors.dart';\nimport 'package:flutter/material.dart';\n\nclass NavLink extends StatelessWidget {\n  final String title;\n  final int index;\n  final int currentIndex;\n  final VoidCallback onTap;\n  final double fontSize;\n\n  const NavLink({super.key, \n    required this.title,\n    required this.index,\n    required this.currentIndex,\n    required this.onTap,\n    this.fontSize = 14.0,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    final bool isActive = index == currentIndex;\n\n    return TextButton(\n      onPressed: onTap,\n      style: TextButton.styleFrom(\n        splashFactory: NoSplash.splashFactory,\n        overlayColor: Colors.transparent,\n        foregroundColor: isActive ? kTextColor : Colors.grey,\n        \n        textStyle: TextStyle(\n          fontFamily: 'JetBrainsMono',\n          fontSize: fontSize,\n          fontWeight: isActive ? FontWeight.bold : FontWeight.normal,\n        ),\n      ),\n      child: Text(title),\n    );\n  }\n}",
};
